    ////////////////////////////////////////////////////////


    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    TwistExpander_Rigel_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Rigel_Arx::SEED_B(PARAMS_SEED);

